	private void assertContextualFilter(boolean nested) {
		var values = SimpleValueFactory.getInstance();
		StatementPattern prefix = new StatementPattern(Var.of("s"),
				Var.of("prefixPredicate", values.createIRI("urn:test:prefix")), Var.of("p"));
		Filter filter = new Filter(new StatementPattern(Var.of("s"),
				Var.of("filterPredicate", values.createIRI("urn:test:filter")), Var.of("o")),
				new ValueConstant(values.createLiteral(true)));
		if (nested) {
			filter = new Filter(filter, new ValueConstant(values.createLiteral(true)));
		}
		var call = PackedCostTestSupport.disconnectedFilter(prefix, filter, 100_000.0d);
		PackedCostEstimate output = estimate();
		new LmdbMappedFrontierLearningSession(runtimeWithFact(call.query(), call.factorRelationId()), call.query(),
				true)
						.applyOperator(call.factorRelationId(), new int[] { call.factorRelationId() }, call.context(),
								output);

		assertEquals(100_000.0d, output.outputRows(), 0.0d,
				"a per-invocation logical fact cannot replace the complete inherited join-prefix cardinality");
		assertNotNull(output.runtimeFeedbackContract(), "physical feedback must remain available");
	}

