	@Test
	void reopenedLegacyMappedPopulationFactCannotPoisonCurrentDestination() throws Exception {
		var call = semiAntiQuery();
		LmdbEstimatorRuntime runtime = mock(LmdbEstimatorRuntime.class);
		var session = new LmdbMappedFrontierLearningSession(runtime, call.query(), true);
		var current = operatorEstimate(session, call.leftRelationId(), emptyContext()).runtimeFeedbackContract();
		var descriptor = (LmdbRuntimeFeedbackDescriptor) current.descriptor();
		String applicability = descriptor.applicability().externalForm();
		LearningApplicability legacy = LearningApplicability.parse(
				applicability.substring(0, applicability.lastIndexOf('|') + 1) + "1");
		assertNotNull(legacy);
		var legacyDescriptor = new LmdbRuntimeFeedbackDescriptor(descriptor.legacyLogicalKey(),
				descriptor.legacyPhysicalKey(), descriptor.logicalKey(), legacy, descriptor.physicalKey(),
				descriptor.logicalGroupOrigin(), descriptor.featureEnvelope(), descriptor.exactFilterSurfaceKey(),
				descriptor.generalizedFilterSurfaceKey());
		Path path = temporary.resolve("persistent-populations");
		Files.createDirectories(path);
		Files.writeString(path.resolve("metadata.bin"), "metadata");
		SketchSnapshotIdentity snapshot = new SketchSnapshotIdentity(0x1234L, 0x5678L, 9L);
		LmdbOperatorFeedbackStats feedback = new LmdbOperatorFeedbackStats(path, () -> snapshot);
		publish(feedback, current.withDescriptor(legacyDescriptor), 0L);
		feedback.persistIfDirty();
		LmdbOperatorFeedbackStats reopened = new LmdbOperatorFeedbackStats(path, () -> snapshot);
		assertEquals(0.0d, reopened.exactCardinalityFact(descriptor.logicalKey(), legacy),
				"migration must leave separately addressed compatible evidence intact");
		when(runtime.feedback()).thenReturn(reopened);
		var next = new LmdbMappedFrontierLearningSession(runtime, call.query(), true);
		var output = operatorEstimate(next, call.leftRelationId(), emptyContext());
		assertEquals(100_000.0d, output.outputRows(), 0.0d,
				"the old affected namespace cannot certify a current semantic population");
		publish(reopened, output.runtimeFeedbackContract(), 3L);
		reopened.persistIfDirty();
		when(runtime.feedback()).thenReturn(new LmdbOperatorFeedbackStats(path, () -> snapshot));
		assertEquals(3.0d, operatorEstimate(new LmdbMappedFrontierLearningSession(runtime, call.query(), true),
				call.leftRelationId(), emptyContext()).outputRows());
	}

	@Test
	void mappedRowTransformProofOverridesAnEmptyPrefixWithTrueRowFlag() {
		var call = PackedCostTestSupport.unaryOperator(PlanningGraphDomain.defaultGraph(), twoFilters());
		PackedQueryView query = call.query();
		int first = filteredLeaf(query, Compare.CompareOp.GT);
		int other = filteredLeaf(query, Compare.CompareOp.LT);
		int leaf = query.childRelationId(first, 0);
		LmdbEstimatorRuntime runtime = mock(LmdbEstimatorRuntime.class);
		try (var session = boundedMappedSession(query, runtime)) {
			var input = physicalEstimate();
			session.estimateLeaf(leaf, emptyContext(), input);
			var firstOutput = physicalEstimate();
			session.refineOperator(first, call.operatorContext(input.outputRows(), input.evidenceStateId()),
					firstOutput);
			var otherOutput = physicalEstimate();
			session.refineOperator(other, call.operatorContext(input.outputRows(), input.evidenceStateId()),
					otherOutput);
			assertEquals(firstOutput.outputRows(), otherOutput.outputRows());
			assertEquals(firstOutput.plannedDoubleMetric("plannedFrontierFactorCount", -1.0d),
					otherOutput.plannedDoubleMetric("plannedFrontierFactorCount", -1.0d));
			var correctContext = call.operatorContext(firstOutput.outputRows(), firstOutput.evidenceStateId());
			assertEquals(0, correctContext.prefixRelationCount());
			assertTrue(correctContext.prefixRelationsDescribeRows());
			var correct = physicalEstimate();
			session.refineOperator(call.operatorRelationId(), correctContext, correct);
			assertTrue(correct.runtimeFeedbackContract().admits(RuntimeFeedbackContract.EXACT_FACT_ELIGIBLE),
					"the actual encoded complete child retains whole-expression learning");
			var mismatched = physicalEstimate();
			session.refineOperator(call.operatorRelationId(),
					call.operatorContext(otherOutput.outputRows(), otherOutput.evidenceStateId()), mismatched);
			assertNotNull(mismatched.runtimeFeedbackContract());
			assertFalse(mismatched.runtimeFeedbackContract().admits(RuntimeFeedbackContract.EXACT_FACT_ELIGIBLE),
					"equal tuple lineage and row estimates cannot authenticate a different applied predicate");
			assertFalse(mismatched.runtimeFeedbackContract().admits(RuntimeFeedbackContract.ADMIT_LOGICAL));
			assertTrue(mismatched.runtimeFeedbackContract().admits(RuntimeFeedbackContract.ADMIT_PHYSICAL));
		}
	}

	@Test
	void ancestorJoinIncludesAppliedPredicatesAndRetainsBagCommutation() {
		var call = PackedCostTestSupport.binaryOperator(PlanningGraphDomain.defaultGraph(),
				new Join(twoFilters(), pattern("other", "otherValue")));
		PackedQueryView query = call.query();
		int first = filteredLeaf(query, Compare.CompareOp.GT);
		int other = filteredLeaf(query, Compare.CompareOp.LT);
		int leaf = query.childRelationId(first, 0);
		LmdbEstimatorRuntime runtime = mock(LmdbEstimatorRuntime.class);
		try (var session = mappedSession(query, runtime)) {
			var input = estimate();
			session.estimateLeaf(leaf, emptyContext(), input);
			var firstOutput = estimate();
			session.refineOperator(first, call.operatorContext(input.outputRows(), Double.NaN,
					input.evidenceStateId(), 0), firstOutput);
			var otherOutput = estimate();
			session.refineOperator(other, call.operatorContext(input.outputRows(), Double.NaN,
					input.evidenceStateId(), 0), otherOutput);
			var right = estimate();
			session.estimateLeaf(call.rightRelationId(), emptyContext(), right);
			var firstJoin = estimate();
			session.refineIntermediateJoin(call.operatorContext(firstOutput.outputRows(), right.outputRows(),
					firstOutput.evidenceStateId(), right.evidenceStateId()), firstJoin);
			var otherJoin = estimate();
			otherJoin.setContextualRows(222.0d, 222.0d);
			session.refineIntermediateJoin(call.operatorContext(otherOutput.outputRows(), right.outputRows(),
					otherOutput.evidenceStateId(), right.evidenceStateId()), otherJoin);
			assertNotEquals(descriptor(firstJoin).logicalKey(), descriptor(otherJoin).logicalKey(),
					"a join's learned population includes predicates applied before the join");
			var reversed = estimate();
			session.refineIntermediateJoin(call.operatorContext(right.outputRows(), firstOutput.outputRows(),
					right.evidenceStateId(), firstOutput.evidenceStateId()), reversed);
			assertEquals(descriptor(firstJoin).logicalKey(), descriptor(reversed).logicalKey(),
					"complete BAG join commutation preserves a semantic destination");
			var repeated = estimate();
			session.refineIntermediateJoin(call.operatorContext(firstOutput.outputRows(), firstOutput.outputRows(),
					firstOutput.evidenceStateId(), firstOutput.evidenceStateId()), repeated);
			assertNotEquals(descriptor(firstOutput).logicalKey(), descriptor(repeated).logicalKey(),
					"joining a bag to itself does not deduplicate its semantic occurrence");
			var pair = new PackedCostTestSupport.PairCostCall(query, call.leftRelationId(), call.rightRelationId());
			var wrongCandidate = pair.intermediateJoinContext(otherJoin.outputRows(), otherJoin.evidenceStateId(),
					firstOutput.outputRows(), right.outputRows(), firstOutput.evidenceStateId(),
					right.evidenceStateId());
			var physical = estimate();
			physical.setContextualRows(17.0d, 17.0d);
			physical.putPlannedStringMetric("optimizer.physicalJoinImplementation", "independent-hash");
			session.refineIntermediateJoin(wrongCandidate, physical);
			assertEquals(17.0d, physical.outputRows(),
					"a same-leaf candidate with different predicates cannot restore222");
			assertEquals(descriptor(firstJoin).logicalKey(), descriptor(physical).logicalKey());
		}
	}

