	@ParameterizedTest
	@CsvSource({ "false,false", "false,true", "true,false", "true,true" })
	void completedTreePublicationHonorsTheTypedPopulationQualification(boolean qualified, boolean contractLost) {
		var call = semiAntiQuery();
		var session = new LmdbMappedFrontierLearningSession(mock(LmdbEstimatorRuntime.class), call.query(), true);
		var output = estimate();
		session.applyOperator(call.leftRelationId(), new int[] { call.leftRelationId() }, emptyContext(), output,
				qualified);
		var identity = descriptor(output);
		TupleExpr node = call.query().materializeRelation(call.leftRelationId()).clone();
		PlanningGraphDomains.capture(node, PlanningGraphDomain.defaultGraph());
		output.plannedStringMetrics().forEach(node::setStringMetricPlanned);
		output.plannedDoubleMetrics().forEach(node::setDoubleMetricPlanned);
		node.setRuntimeFeedbackContract(contractLost ? null : output.runtimeFeedbackContract());
		node.setStringMetricPlanned("optimizer.costEventDigest", "controlled-completed-event");
		node.setStringMetricPlanned("optimizer.frontierStateDigest", "controlled-completed-state");
		node.setCostFeedbackTrackingEnabled(true);
		node.setCostFeedbackExpectedRows(100_000.0d);
		node.setCostFeedbackExpectedWorkRows(100_000.0d);
		node.setResultSizeEstimate(100_000.0d);
		node.setCostEstimate(100_000.0d);
		node.setCostFeedbackActualRows(3L);
		node.setCostFeedbackActualWorkRows(3.0d);
		node.setCostFeedbackCloseCountActual(1L);
		node.setCostFeedbackCompletedActual(true);
		node.setLongMetricActual(TelemetryMetricNames.EXHAUSTED_CLOSE_COUNT_ACTUAL, 1L);
		LmdbOperatorFeedbackStats feedback = new LmdbOperatorFeedbackStats(temporary.resolve("legacy-" + qualified));
		feedback.recordCompletedQuery(node);
		var gate = feedback.logicalDimensionDecision(identity.logicalKey(), identity.applicability(),
				FrontierCostDimension.OUTPUT_ROWS, identity.featureEnvelope(), 100_000.0d).gate();
		assertEquals(qualified && !contractLost ? 1L : 0L, gate.exactCellObservations(),
				"completed metadata cannot replace a missing or declined immutable population qualification");
	}

